	"fmt"
	"sync"
	"sync/atomic"
)

// Pool is a fixed-size worker pool that executes submitted functions concurrently.
type Pool struct {
	workers    int
	taskCh     chan func() error
	errCh      chan error
	wg         sync.WaitGroup
	mu         sync.Mutex
	shutdown   bool
	closed     bool
	errs       []error
	errsMu     sync.Mutex
	panicCount atomic.Int64
}

// New creates a new Pool with n workers.
func New(n int) *Pool {
	if n <= 0 {
		n = 1
	}
	p := &Pool{
		workers: n,
		taskCh:  make(chan func() error),
		errCh:   make(chan error, n*2),
	}
	for i := 0; i < n; i++ {
		p.wg.Add(1)
		go p.worker()
	}
	return p
}

// worker is the main loop for each worker goroutine.
func (p *Pool) worker() {
	defer p.wg.Done()
	for task := range p.taskCh {
		p.safeRun(task)
	}
}

// safeRun executes a task, recovering from panics and collecting errors.
func (p *Pool) safeRun(task func() error) {
	defer func() {
		if r := recover(); r != nil {
			p.panicCount.Add(1)
			err := fmt.Errorf("panic in worker: %v", r)
			p.collectError(err)
		}
	}()
	if err := task(); err != nil {
		p.collectError(err)
	}
}

